{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "The inclusion criteria for the systematic review were a) randomised controlled trials (RCT) and observational studies (retrospective, prospective, crosssectional, longitudinal, case-control and cohort), b) whose objective was to determine the prevalence of respiratory symptoms in patients presenting with COVID-19, c) laboratory-confirmed COVID-19 infection by quantitative real-time polymerase chain reaction (qRT-PCR) or polymerase chain reaction dual fluorescence (PCR), d) hospitalised adult patients (≥ 18 years), e) follow-up from 30 days after Covid-19 infection, f) follow-up from 21 days after hospital discharge.",
      "reason": "Study designs, setting/population, outcome focus, and follow-up requirements are all explicitly specified as eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "17 articles were excluded due to wrong outcome (n = 6), wrong population (n = 5), wrong study design (n = 4), duplicate data (n = 1) and for being preprint (n = 1).",
      "reason": "Publication status (preprints excluded) is indicated, but no explicit criteria on dissemination year or language restrictions are reported."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_14",
      "quote": "wrong outcome ( n ¼ 6)",
      "reason": "The review reports exclusion for 'wrong outcome' but does not distinguish whether this meant outcomes were not measured versus outcomes measured but results not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": "text_7",
      "quote": null,
      "reason": "No evidence describes how studies were grouped for the syntheses or links groups to review objective comparisons; only pooled prevalence meta-analysis is implied."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Following the acute phase of COVID-19, there is increasing awareness of patients with 'long COVID'",
      "reason": "A partial rationale (awareness of long COVID) appears to underpin the follow-up restrictions, but rationales for other restrictions (e.g., excluding interventions, systematic reviews) are not provided."
    }
  ],
  "confidence": 88
}

